// Format one markdown table/list row from the HA event payload.
// Normalize: clients/tests may send fields on body or directly on $json.
const b = $json.body ?? $json;
const ts = b.ts ?? new Date().toISOString();
const event = b.event ?? 'unknown';
const entity = b.entity ?? 'unknown';
const from = b.from ?? '';
const to = b.to ?? '';
const row = `- ${ts} | ${event} | ${entity} | ${from} \u2192 ${to}`;
return [{ json: { row, ts, event, entity, from, to } }];
